from rules import SOLVERS


def solve(data):
    return {component_id: solver(data[component_id])
            for component_id, solver in SOLVERS.items()}

from itertools import combinations
import heapq


def dependency_solver(data, order, maximize):
    packages = data["packages"]
    names = sorted(packages, reverse=(order == "descending"))
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    choices = {}
    for name in names:
        choices[name] = [None] + [row for row in packages[name]
            if row["version"] not in blocked.get(name, [])
            and (name not in pins or row["version"] == pins[name])]

    best = None
    best_vector = None
    assignment = {}

    def check():
        edges = {}
        pending = list(data["roots"])
        for name, bounds in data["roots"].items():
            row = assignment.get(name)
            if row is None or not bounds[0] <= row["version"] <= bounds[1]:
                return None
        reachable = set()
        while pending:
            name = pending.pop()
            if name in reachable:
                continue
            row = assignment.get(name)
            if row is None:
                return None
            reachable.add(name)
            deps = [d for d in row.get("deps", [])
                    if not d.get("feature") or d["feature"] in features]
            edges[name] = []
            for dep in deps:
                other = dep["name"]
                chosen = assignment.get(other)
                if chosen is None or not dep["min"] <= chosen["version"] <= dep["max"]:
                    return None
                edges[name].append(other)
                pending.append(other)
        if any(assignment[n] is not None for n in names if n not in reachable):
            return None
        done, active = set(), set()
        def visit(n):
            if n in active:
                return False
            if n in done:
                return True
            active.add(n)
            if any(not visit(x) for x in edges.get(n, [])):
                return False
            active.remove(n)
            done.add(n)
            return True
        if not all(visit(n) for n in reachable):
            return None
        return {n: assignment[n]["version"] for n in reachable}

    def search(i):
        nonlocal best, best_vector
        if i == len(names):
            installed = check()
            if installed is None:
                return
            vector = tuple(installed.get(n, -1) for n in names)
            if best_vector is None or (vector > best_vector if maximize else vector < best_vector):
                best_vector, best = vector, installed
            return
        name = names[i]
        for row in choices[name]:
            assignment[name] = row
            search(i + 1)
    search(0)
    return {"versions": best} if best is not None else {"error": "unsatisfiable"}


def _dependency(order, maximize):
    return lambda data: dependency_solver(data, order, maximize)


def ledger(data):
    events = data["events"]
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for pos, event in enumerate(events):
        seq = event.get("sequence", 0)
        if seq > cutoff:
            continue
        ident = event.get("id", "anonymous:" + str(pos))
        key = (seq, event.get("revision", 0), pos)
        if ident not in winners or key > winners[ident][0]:
            winners[ident] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]
    def rounded(num):
        if mode == "floor":
            return num // 10000
        return (num + 5000) // 10000

    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount))
        tax = rounded(net * event.get("tax_bp", 0))
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def schedule(data):
    jobs = data["jobs"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    k = data["k"]
    best_ids = None
    best_value = None
    for subset in combinations(jobs, k):
        ids = tuple(sorted(job["id"] for job in subset))
        if any(i in blocked for i in ids) or not mandatory.issubset(ids):
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        ordered = sorted(subset, key=lambda j: (j["start"], j["end"], j["id"]))
        if any(ordered[i]["start"] < ordered[i-1]["end"]
               for i in range(1, len(ordered))):
            continue
        value = sum(job["value"] for job in subset)
        if best_value is None or value > best_value or (value == best_value and ids < best_ids):
            best_value, best_ids = value, ids
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def routes(data):
    required = data.get("required", [])
    bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)
    source, target = data["source"], data["target"]
    start, deadline, coupons = data["start"], data["deadline"], data["coupons"]
    initial_mask = bit.get(source, 0)
    state = (source, initial_mask, coupons)
    dist = {state: start}
    queue = [(start, source, initial_mask, coupons)]
    while queue:
        arrival, node, mask, left = heapq.heappop(queue)
        current = (node, mask, left)
        if dist.get(current) != arrival:
            continue
        if node == target and mask == full and left == 0:
            return {"arrival": arrival}
        for edge in graph[node]:
            depart = max(arrival, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], left)]
            if left:
                options.append((max(2, edge["duration"] - edge.get("discount", 0)), left - 1))
            newmask = mask | bit.get(edge["v"], 0)
            for duration, newleft in options:
                when = depart + duration
                nxt = (edge["v"], newmask, newleft)
                if when <= deadline and when < dist.get(nxt, float("inf")):
                    dist[nxt] = when
                    heapq.heappush(queue, (when, *nxt))
    return {"arrival": None}


SOLVERS = {
    "component_01": _dependency("ascending", False),
    "component_02": _dependency("descending", True),
    "component_03": _dependency("descending", False),
    "component_04": _dependency("ascending", True),
    "component_05": _dependency("ascending", False),
    "component_06": ledger,
    "component_07": schedule,
    "component_08": routes,
}
